import{_ as s,C as i,o as d,c as h,a2 as n,E as a,j as o,a as r}from"./chunks/framework.CGSzHL4z.js";const f=JSON.parse('{"title":"Constraints, drivers and Motion Warp","description":"","frontmatter":{},"headers":[],"relativePath":"features/constraints-and-drivers.md","filePath":"features/constraints-and-drivers.md","lastUpdated":1792713747000}'),l={name:"features/constraints-and-drivers.md"};function c(p,t,g,m,w,u){const e=i("Screenshot");return d(),h("div",null,[t[0]||(t[0]=n('<h1 id="constraints-drivers-and-motion-warp" tabindex="-1">Constraints, drivers and Motion Warp <a class="header-anchor" href="#constraints-drivers-and-motion-warp" aria-label="Permalink to &quot;Constraints, drivers and Motion Warp&quot;">​</a></h1><p>These three kinds of block set a value from something else in the scene instead of from keys alone. A <strong>constraint</strong> moves an actor&#39;s root or a joint: aim a camera at a character, keep a head inside its limits, plant a foot. A <strong>driver</strong> sets any value from a measurement, such as a camera&#39;s FieldOfView from how far a character is. A <strong>Motion Warp</strong> bends an actor&#39;s path so it lands on its real target, wherever a game puts it.</p><p>All three sit on a row&#39;s <strong>Stack</strong> lane with generators. A row&#39;s blocks apply top to bottom, each on the result of the ones above.</p>',3)),a(e,{name:"fig-constraint-timeline",caption:"Stack lanes on the Timeline: a camera with Track To and Shake, and a Head with Damped Track and Limit Rotation."}),t[1]||(t[1]=n('<h2 id="constraints" tabindex="-1">Constraints <a class="header-anchor" href="#constraints" aria-label="Permalink to &quot;Constraints&quot;">​</a></h2><p>Right click a root or joint row&#39;s header, or its lane&#39;s empty space, and choose <strong>Add constraint</strong>:</p><table tabindex="0"><thead><tr><th>Group</th><th>Constraints</th></tr></thead><tbody><tr><td>Track</td><td>Track To, Damped Track, Locked Track</td></tr><tr><td>Copy</td><td>Copy Location, Copy Rotation, Copy Transforms</td></tr><tr><td>Limit</td><td>Limit Location, Limit Rotation, Limit Distance</td></tr><tr><td>Relationship</td><td>Floor, Lock (on a joint row), Child Of</td></tr><tr><td>Motion</td><td>Delay, Face Motion, Horizon Lock</td></tr><tr><td>Custom</td><td>Your own ModuleScripts tagged <code>AcesMotionConstraint</code> (see <a href="./../extend/custom-constraints">Custom constraints</a>)</td></tr></tbody></table><p>A new constraint spans the keys selected on that row. With none selected it spans a camera&#39;s current shot, or runs from where you clicked to the scene end. Its target is the Explorer selection when that&#39;s part of the cast; otherwise you click the target in the viewport, or press <code>Esc</code> to pick one later in the Inspector. Constraints can&#39;t go on property rows, since they drive positions and rotations.</p>',4)),a(e,{name:"feat-turret",caption:"A Damped Track on the turret aims it at the walker's head as the walker crosses the set; the dashed line shows what it aims at. The drone beside it hovers on Oscillate and Wiggle generators."}),t[2]||(t[2]=o("p",null,'Blocks draw in mint with their target in the label ("Track To · r2 · Head"). A block with no target reads "No target" and does nothing. A missing target draws as failed ("Head missing"), and a target that depends on what it drives draws "Loop, ignored".',-1)),a(e,{name:"feat-limitrot",caption:"Limit Rotation on a head keyed to look 75 degrees each way: the arc and its handles mark the allowed range (Y -35 to 35), and the head stops at its edges."}),t[3]||(t[3]=o("p",null,[o("strong",null,"Lock"),r(" holds a hand or foot where it was at the lock's first frame while the limb above bends to keep it there: a planted foot while the hips move, a hand on a rail. Give it a target and the part sticks to that target instead. Select keys on a hand or foot row and right click > "),o("strong",null,"Lock"),r(", or pick a part in the viewport and press "),o("code",null,"Shift+L"),r(". Posing a locked part keys the lock's "),o("strong",null,"Spot"),r(", so one lock can cover the whole timeline.")],-1)),a(e,{name:"guide-lock",caption:"Both feet locked: the hips dip into a squat and the legs bend to keep the feet where they stand."}),t[4]||(t[4]=o("h3",{id:"the-constraint-panel",tabindex:"-1"},[r("The constraint panel "),o("a",{class:"header-anchor",href:"#the-constraint-panel","aria-label":'Permalink to "The constraint panel"'},"​")],-1)),a(e,{name:"feat-constraint",caption:"Rival's Head Stack holding a Damped Track bar aimed at Hero/Head and a Shake bar, with the Inspector's constraint panel: Timing, Target, Settings with Aim axis -Z Front, Blend with Influence, Fade in and out and Distance fade, and Preset."}),t[5]||(t[5]=n('<p>Select a constraint block for its panel: <strong>Timing</strong>, <strong>Target</strong> (the part list, a viewport pick button and <strong>Use selection</strong>), <strong>Settings</strong> for its kind, <strong>Blend</strong> and <strong>Preset</strong>.</p><ul><li><strong>-Z Front</strong> in the axis dropdowns is Roblox&#39;s front.</li><li>A target can be a <strong>Point</strong> instead of a part: a spot with X, Y and Z key diamonds that you move with the gizmo.</li><li><strong>Distance fade</strong> (in Blend) keeps the constraint at full strength within <strong>Full within</strong> studs of what it measures to and fades it out by <strong>None beyond</strong>.</li><li><strong>Influence</strong>, <strong>Roll</strong>, <strong>Delay</strong> and <strong>Bank</strong> have key diamonds.</li></ul><p>The Stack section, at the end of an actor&#39;s or joint&#39;s properties, lists every block on the row in the order it runs. Drag an entry up or down to reorder it, or click its eye to mute it.</p><h2 id="drivers" tabindex="-1">Drivers <a class="header-anchor" href="#drivers" aria-label="Permalink to &quot;Drivers&quot;">​</a></h2><p>Right click a row&#39;s header or its lane&#39;s empty space and choose <strong>Add driver</strong>:</p><table tabindex="0"><thead><tr><th>Driver</th><th>Reads</th></tr></thead><tbody><tr><td><strong>Copy</strong></td><td>One property&#39;s whole value, or a joint&#39;s pose or placement</td></tr><tr><td><strong>Distance</strong></td><td>How far apart two things are</td></tr><tr><td><strong>Axis</strong></td><td>One axis of an object&#39;s position or rotation</td></tr><tr><td><strong>Speed</strong></td><td>How fast something moves or turns</td></tr><tr><td><strong>Property</strong></td><td>A property or attribute</td></tr></tbody></table><p>Drivers go on any row a generator takes, including one channel of a joint or vector. A new driver covers the whole scene. When you add it nothing changes yet: <strong>Out Low</strong> and <strong>Out High</strong> both start at the row&#39;s current value. Set them to the range it should drive between.</p><p>Driver blocks draw in tangerine, labelled with what they read and what they drive (&quot;Distance · r2 &gt; FieldOfView&quot;).</p><h3 id="the-driver-panel" tabindex="-1">The driver panel <a class="header-anchor" href="#the-driver-panel" aria-label="Permalink to &quot;The driver panel&quot;">​</a></h3>',9)),a(e,{name:"insp-driver",caption:"A Distance driver's panel: Source with the target part, the live Now readout, the Mapping graph and the Map ranges."}),t[6]||(t[6]=n("<p>The <strong>Source</strong> section picks what it reads, with <strong>Now</strong> showing the source at the playhead (&quot;23.4 studs&quot;). <strong>Map</strong> sets <strong>In Low</strong> and <strong>In High</strong> (each with a <strong>Capture</strong> button: scrub to a frame and capture the source there), <strong>Out Low</strong> and <strong>Out High</strong>, a <strong>Shape</strong> from the ease presets, and <strong>Clamp</strong> and <strong>Invert</strong>. On a whole Color3, a colour ramp edited in the gradient editor takes the place of Out Low and Out High.</p>",1)),a(e,{name:"feat-lamp",caption:"A Distance driver on a lamp's Brightness: as the walker comes within 3 studs the light rises to 8, and fades back to 0 by 12 studs. The viewport readout and the mapping dot follow along."}),t[7]||(t[7]=n('<p>The <strong>Mapping</strong> graph plots source against output. Drag a dashed range line to change that range; <code>Shift</code> drags both ends. <strong>Smooth</strong> averages the source over a number of frames.</p><h2 id="motion-warp" tabindex="-1">Motion Warp <a class="header-anchor" href="#motion-warp" aria-label="Permalink to &quot;Motion Warp&quot;">​</a></h2><p>You animate the trip once against the stand-ins. In a game the path is re-fitted between where it really starts and where the target really is, so a fireball still lands on a unit three times further away and an arc stays an arc at any range.</p><p>Add it from an actor&#39;s or root row&#39;s menu: <strong>Add Motion Warp</strong>. It covers the selected root keys, else the next half second; with no root keys yet it keys both ends so it flies at once. On a joint row it bends a chain so that joint reaches the target, for a claw, a bite or a tentacle.</p>',4)),a(e,{name:"fig-warp-timeline",caption:"Motion Warp bars on Stack lanes: Caster/RightHand to Target/UpperTorso with a faded 'plays 1.2 s here' extension, a Face Motion, Orb to Point, keyed Weight, Arc and Arc turn setting rows, and a Joints warp on a crane claw with Limit Rotation."}),a(e,{name:"guide-warp",caption:"A Motion Warp on a thrown orb: the arc is the path it flies, ending on the target's chest, with a handle to shape it and a dashed line to what it lands on."}),t[8]||(t[8]=n("<p>The panel&#39;s <strong>Path</strong> section sets <strong>Starts from</strong> and <strong>Lands on</strong>, and whether it follows a moving target or aims where it was at launch. <strong>Path shape</strong> switches on a live shape (Straight, Lob, High arc, Spiral, Zig-zag) in place of your keyed path; <strong>Bake shape to keys</strong> writes it into the root keys. <strong>Arc</strong> and <strong>Arc turn</strong> are keyable. <strong>Travel time</strong> keeps the keyed length or times the trip <strong>By speed</strong>, within a Min and Max.</p>",1)),a(e,{name:"fig-warp-panel",caption:"The Motion Warp panel in the Inspector: Timing, Path, Travel time, Blend and Preset."}),t[9]||(t[9]=n('<p>To ease the trip, select the warp bar with no keys selected and press <code>E</code>.</p><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li><strong>Bake to keys</strong> in a block&#39;s menu writes the result as keys and removes the block, along with every block above it on the row that overlaps it. The row header&#39;s <strong>Bake stack</strong> bakes the whole stack.</li><li>Baking a block that follows something the game fills in (the local player, a tagged object) asks first, since baking freezes it to the stand-in.</li><li>To write your own constraint, choose <strong>Add constraint</strong> &gt; <strong>New custom constraint...</strong> for a typed, commented template. <a href="./../extend/custom-constraints">Custom constraints</a> walks through it.</li><li>A native export bakes a rig&#39;s constrained joints and root into its animation, and plays a Motion Warp as it is for the stand-ins. Constraints on other actors play with the runtime.</li></ul><h2 id="compared-to-roblox-s-animation-editor" tabindex="-1">Compared to Roblox&#39;s Animation Editor <a class="header-anchor" href="#compared-to-roblox-s-animation-editor" aria-label="Permalink to &quot;Compared to Roblox&#39;s Animation Editor&quot;">​</a></h2><p>Roblox&#39;s Animation Editor has IK for posing, but no constraints, drivers or Motion Warp on its timeline: everything it plays comes from keys on one rig. In AcesMotion a head can keep aiming at another actor, a camera&#39;s lens can respond to distance, and a projectile&#39;s path can re-fit to wherever its target stands when the game plays the scene.</p>',5))])}const b=s(l,[["render",c]]);export{f as __pageData,b as default};
